      "additionalProperties": false,
      "required": [
        "status",
        "summary"
      ],
      "properties": {
        "status": {
          "type": "string",
          "enum": [
            "PASS",
            "ADJUST",
            "INCONCLUSIVE",
            "NOT_PRESENT"
          ]
        },
        "summary": {
          "type": "string",
          "minLength": 15
        }
      }
    },
    "music": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status",
        "summary"
      ],
      "properties": {
        "status": {
          "type": "string",
          "enum": [
            "PASS",
            "ADJUST",
            "INCONCLUSIVE",
            "NOT_PRESENT"
          ]
        },
        "summary": {
          "type": "string",
          "minLength": 15
        }
      }
    },
    "timing": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status",
        "summary"
      ],
      "properties": {
        "status": {
          "type": "string",
          "enum": [
            "PASS",
            "ADJUST",
            "INCONCLUSIVE",
            "NOT_PRESENT"
          ]
        },
        "summary": {
          "type": "string",
          "minLength": 15
        }
      }
    },
    "moments": {
      "type": "array",
      "minItems": 3,
      "maxItems": 12,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "startSeconds",
          "endSeconds",
          "heard",
          "action"
        ],
        "properties": {
          "startSeconds": {
            "type": "number",
            "minimum": 0
          },
          "endSeconds": {
            "type": "number",
            "exclusiveMinimum": 0
          },
          "heard": {
            "type": "string",
            "minLength": 10
          },
          "action": {
            "type": "string",
            "minLength": 5
          }
        }
      }
    },
    "limitations": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 10
      }
    }
  }
}


